<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin','editor']);$pdo=db();
if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='save'){$id=(int)($_POST['id']??0);$d=[trim($_POST['title_en']??''),trim($_POST['title_am']??''),trim($_POST['description_en']??''),trim($_POST['description_am']??''),trim($_POST['cover_image']??'')];if($id){$st=$pdo->prepare('UPDATE gallery_albums SET title_en=?,title_am=?,description_en=?,description_am=?,cover_image=? WHERE id=?');$st->execute([...$d,$id]);}else{$st=$pdo->prepare('INSERT INTO gallery_albums(title_en,title_am,description_en,description_am,cover_image) VALUES(?,?,?,?,?)');$st->execute($d);}log_admin($id?"Updated gallery album #$id":'Created gallery album');flash('admin_success','Gallery album saved.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM gallery_albums WHERE id=?')->execute([$id]);log_admin("Deleted gallery album #$id");flash('admin_success','Album deleted.');}}catch(Throwable $e){flash('admin_error','Gallery error: '.$e->getMessage());}redirect('admin/gallery.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM gallery_albums WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT a.*,COUNT(g.id) image_count FROM gallery_albums a LEFT JOIN gallery_images g ON g.album_id=a.id GROUP BY a.id ORDER BY a.created_at DESC')->fetchAll();admin_page('Gallery','gallery','Create albums and organize gallery photos. Upload photos from Media Manager.');admin_flash();
?><div class="admin-panel"><h2><?= $edit?'Edit Album':'Create Album' ?></h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="admin-form-grid"><label>Album title (English)<input name="title_en" required value="<?=e($edit['title_en']??'')?>"></label><label>Album title (Amharic)<input name="title_am" value="<?=e($edit['title_am']??'')?>"></label></div><div class="admin-form-grid"><label>Description (English)<textarea name="description_en" rows="4"><?=e($edit['description_en']??'')?></textarea></label><label>Description (Amharic)<textarea name="description_am" rows="4"><?=e($edit['description_am']??'')?></textarea></label></div><label>Cover image path<input name="cover_image" placeholder="assets/images/gallery/cover.jpg" value="<?=e($edit['cover_image']??'')?>"></label><button class="btn primary">Save Album</button></form></div><div class="admin-panel"><h2>Albums</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Album</th><th>Images</th><th>Cover</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title_en'])?></td><td><?=e((string)$r['image_count'])?></td><td><?=e($r['cover_image']?:'—')?></td><td><a class="btn small outline" href="gallery.php?edit=<?=$r['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete album?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div><p class="muted">Tip: use Media Manager → Gallery to upload photos. The public Gallery also shows uploaded gallery images even before you create an album.</p></div><?php admin_end(); ?>
